//! One fixed resident socket under the original Root-controlled runtime parent.

use super::*;
use codex_hepta_types::Digest32;
use std::path::PathBuf;

pub(crate) struct ResidentSocketGuard { _guard: SocketGuard }

pub(crate) struct ResidentListener {
    listener: tokio::net::UnixListener,
    guard: ResidentSocketGuard,
    path: PathBuf,
    device: u64,
    inode: u64,
}

impl ResidentListener {
    pub(crate) fn bind_original(
        config: &HostAuthorityServiceConfig,
        profile: Digest32,
    ) -> io::Result<Self> {
        // SAFETY: these calls only inspect current credentials.
        if unsafe { libc::getuid() } != 0 || unsafe { libc::geteuid() } != 0 {
            return Err(io::Error::other("resident listener requires original Root"));
        }
        let parent = config.sockets.observation.parent()
            .ok_or_else(|| io::Error::other("missing original runtime parent"))?;
        let path = parent.join(format!("lr3-{}.sock", &profile.to_string()[..32]));
        validate_lane_paths(&[&path], config.peer_gid)?;
        // UnixListener::bind is create-only. Never unlink an occupied name.
        let listener = UnixListener::bind(&path)?;
        let created = std::fs::symlink_metadata(&path)?;
        let guard = SocketGuard(vec![(path.clone(), created.dev(), created.ino())]);
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o660))?;
        let node = std::fs::symlink_metadata(&path)?;
        if node.uid() != 0 || node.gid() != config.peer_gid
            || node.nlink() != 1 || node.mode() & 0o7777 != 0o660
            || (node.dev(), node.ino()) != (created.dev(), created.ino())
        {
            return Err(io::Error::other("original resident socket custody differs"));
        }
        validate_lane_paths(&[&path], config.peer_gid)?;
        listener.set_nonblocking(true)?;
        Ok(Self {
            listener: tokio::net::UnixListener::from_std(listener)?,
            guard: ResidentSocketGuard { _guard: guard }, path, device: node.dev(), inode: node.ino(),
        })
    }

    pub(crate) fn original_node(&self) -> (&PathBuf, u64, u64) {
        (&self.path, self.device, self.inode)
    }

    /// Consume one connection or fail. There is no accept retry after refusal.
    pub(crate) async fn accept_original(self, end: Instant) -> io::Result<(std::os::unix::net::UnixStream, ResidentSocketGuard)> {
        if Instant::now() >= end {
            return Err(io::Error::other("resident handoff deadline elapsed"));
        }
        let (stream, _) = tokio::time::timeout_at(
            tokio::time::Instant::from_std(end), self.listener.accept(),
        ).await.map_err(|_| io::Error::other("resident accept deadline elapsed"))??;
        if Instant::now() >= end {
            return Err(io::Error::other("resident accept completed after deadline"));
        }
        Ok((stream.into_std()?, self.guard))
        // Keep exact pathname custody until the original service finishes.
    }
}

//! Root-owned learning trust, read separately from deployment and role packets.
//! This file carries already enrolled public credentials, never signing keys.

use std::io;
use std::path::Path;

use codex_hepta_learning_ledger::AuthenticatedPrincipalV1;
use codex_hepta_learning_ledger::LearningEvidenceRoleV1;
use codex_hepta_learning_ledger::LearningEvidenceTrustV1;
use codex_hepta_learning_ledger::LearningEvidenceVerifierV1;
use codex_hepta_learning_ledger::TrustedLearningSignerV1;
use codex_hepta_types::Digest32;
use codex_hepta_types::StableId;
use serde::Deserialize;
use serde::Serialize;

use crate::authority_host_config::read_root_json;

const PURPOSE: &str = "hepta.host-resident-learning.trusted-evidence.v3";

#[path = "authority_host_task_prefreeze_trust.rs"]
mod original_source;
pub(super) use original_source::{OriginalDistributionPin, OriginalSourceTrust};

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct TrustFile {
    schema_version: u32,
    purpose: String,
    scope_digest: String,
    objective_digest: String,
    authority_epoch: u64,
    signers: Vec<Signer>,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Signer {
    principal: Principal,
    controller_id: String,
    verifying_key: [u8; 32],
    roles: Vec<Role>,
    revoked_at: Option<u64>,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Principal {
    principal_id: String,
    credential_chain_digest: String,
    signing_key_digest: String,
    scope_digest: String,
    authority_epoch: u64,
    authenticated_at: u64,
    expires_at: u64,
}

#[derive(Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
enum Role {
    Generator,
    Observer,
    Evaluator,
    CreditAllocator,
    UnlearningAuthority,
    Selector,
}

impl From<Role> for LearningEvidenceRoleV1 {
    fn from(value: Role) -> Self {
        match value {
            Role::Generator => Self::Generator,
            Role::Observer => Self::Observer,
            Role::Evaluator => Self::Evaluator,
            Role::CreditAllocator => Self::CreditAllocator,
            Role::UnlearningAuthority => Self::UnlearningAuthority,
            Role::Selector => Self::Selector,
        }
    }
}

/// Root loads this from its independent Root0600 operational trust file. The
/// daemon may reconstruct the same public data only after the private sealed
/// Root enrollment path authenticates its producer and exact recipient.
pub(super) struct OriginalHostTrust {
    pub(super) verifier: LearningEvidenceVerifierV1,
    signers: Vec<TrustedLearningSignerV1>,
    pub(super) encoded: Vec<u8>,
}

impl OriginalHostTrust {
    pub(super) fn read(path: &Path) -> io::Result<Self> {
        let value: TrustFile = read_root_json(path)?;
        Self::from_value(value)
    }

    // Only the private authenticated Root-enrollment receiver calls this.
    pub(super) fn from_root_enrollment(bytes: &[u8]) -> io::Result<Self> {
        if bytes.is_empty() || bytes.len() > crate::HOST_AUTHORITY_BOOTSTRAP_BOUND {
            return Err(io::Error::other("original trust exceeds sealed descriptor bound"));
        }
        Self::from_value(serde_json::from_slice(bytes).map_err(io::Error::other)?)
    }

    fn from_value(value: TrustFile) -> io::Result<Self> {
        let encoded = serde_json::to_vec(&value).map_err(io::Error::other)?;
        if value.schema_version != 3
            || value.purpose != PURPOSE
            || value.signers.is_empty()
            || value.signers.len() > 64
        {
            return Err(io::Error::other("original host learning trust profile differs"));
        }
        let signers = value
            .signers
            .into_iter()
            .map(|signer| {
                let principal = signer.principal;
                Ok(TrustedLearningSignerV1 {
                    principal: AuthenticatedPrincipalV1 {
                        principal_id: StableId::new(principal.principal_id)
                            .map_err(io::Error::other)?,
                        credential_chain_digest: digest(&principal.credential_chain_digest)?,
                        signing_key_digest: digest(&principal.signing_key_digest)?,
                        scope_digest: digest(&principal.scope_digest)?,
                        authority_epoch: principal.authority_epoch,
                        authenticated_at: principal.authenticated_at,
                        expires_at: principal.expires_at,
                    },
                    controller_id: StableId::new(signer.controller_id).map_err(io::Error::other)?,
                    verifying_key: signer.verifying_key,
                    roles: signer.roles.into_iter().map(Into::into).collect(),
                    revoked_at: signer.revoked_at,
                })
            })
            .collect::<io::Result<Vec<_>>>()?;
        let verifier = LearningEvidenceVerifierV1::new(LearningEvidenceTrustV1 {
            scope_digest: digest(&value.scope_digest)?,
            objective_digest: digest(&value.objective_digest)?,
            authority_epoch: value.authority_epoch,
            signers: signers.clone(),
        })
        .map_err(io::Error::other)?;
        Ok(Self { verifier, signers, encoded })
    }

    pub(super) fn observer(
        &self,
        original_actor: &StableId,
        now: u64,
    ) -> io::Result<TrustedLearningSignerV1> {
        let signer = self
            .signers
            .iter()
            .find(|signer| &signer.principal.principal_id == original_actor)
            .ok_or_else(|| io::Error::other("original Material actor is not enrolled"))?;
        self.verifier
            .require_signer_binding(LearningEvidenceRoleV1::Observer, signer, now)
            .map_err(io::Error::other)?;
        Ok(signer.clone())
    }
}

pub(super) fn digest(value: &str) -> io::Result<Digest32> {
    let digest = value.parse::<Digest32>().map_err(io::Error::other)?;
    if digest.to_string() != value {
        return Err(io::Error::other("noncanonical original digest"));
    }
    Ok(digest)
}

//! A single late handoff joins the existing delivery actor, never another loop.

use std::os::unix::net::UnixDatagram;
use std::time::Instant;
use codex_arg0::Arg0DispatchPaths;
use crate::{AgentdConfig, AgentdError};

pub(super) struct PendingResidentEnrollment {
    pub(super) socket: UnixDatagram,
    pub(super) end: Instant,
}

pub(super) async fn run_original(
    config: AgentdConfig,
    arg0_paths: Arg0DispatchPaths,
    pending: PendingResidentEnrollment,
) -> Result<(), AgentdError> {
    let identity = config.identity().clone();
    // The old exclusive Config guard still requires the actual Circuit
    // bootstrap/invocation, Objective profile and AuthBus trust before opt-in.
    let (config, enrollment) = config.with_root_resident_learning_enrollment()?;
    let original = crate::run(config, arg0_paths);
    tokio::pin!(original);
    let receive = crate::root_production_handoff::receive_original_resident_enrollment(
        pending.socket, &identity, pending.end,
    );
    tokio::pin!(receive);
    let root = tokio::select! {
        result = &mut original => return result,
        result = &mut receive => result,
    };
    let joined = match root {
        Err(error) => Err(error),
        Ok(root) => {
            // This ACK confirms only the original local outbox/source join.
            // Root's actual Admit remains solely in the original delivery code.
            let join = crate::AgentdRootResidentEnrollmentV3::enroll_original_root(&enrollment, root);
            tokio::pin!(join);
            tokio::select! {
                result = &mut original => {
                    result?;
                    return Err(AgentdError::Protocol(
                        "resident local enrollment ACK unknown at daemon shutdown".into(),
                    ));
                }
                result = &mut join => result.map_err(|error| AgentdError::Protocol(error.to_string())),
            }
        }
    };
    if let Err(error) = &joined {
        tracing::error!(error = %error, "original resident enrollment refused; no retry or replacement claim");
    }
    // Never drop the ordinary daemon future to hide an enrollment failure.
    // Its existing cancellation, worker cleanup and writer shutdown must finish.
    original.await?;
    joined
}

//! One late V3 Root packet, separate from both original V1 handoffs.

use super::*;
use std::time::Instant;

const FRAME_V3: &[u8] = b"HEPTA_ROOT_RESIDENT_ENROLLMENT_V3";

pub(crate) fn send_original_resident_enrollment(
    socket: UnixDatagram,
    bootstrap: &File,
    root_pidfd: &OwnedFd,
    timeout: Duration,
) -> Result<(), AgentdError> {
    // SAFETY: both calls only inspect the current kernel credentials.
    if unsafe { libc::getuid() } != 0 || unsafe { libc::geteuid() } != 0 {
        return Err(refused("resident enrollment requires original Root"));
    }
    let peer = root_pair(&socket, timeout)?;
    if peer.pid as u32 != std::process::id() {
        return Err(refused("resident enrollment pair belongs to another Root"));
    }
    validate_bootstrap(bootstrap)?;
    require_root_pin(root_pidfd, std::process::id())?;
    send_packet(&socket, FRAME_V3, &[bootstrap.as_raw_fd(), root_pidfd.as_raw_fd()], timeout)
}

pub(crate) async fn receive_original_resident_enrollment(
    socket: UnixDatagram,
    identity: &crate::AgentdIdentity,
    idle_end: Instant,
) -> Result<crate::AgentdRootResidentLearningClientV3, AgentdError> {
    // Idle waiting is bounded by the already running original Root session.
    // The packet carries its own shorter absolute 30-second handoff deadline.
    let peer = root_pair(&socket, Duration::from_secs(30))?;
    if Instant::now() >= idle_end { return Err(refused("resident enrollment expired")); }
    socket.set_nonblocking(true)?;
    let socket = tokio::net::UnixDatagram::from_std(socket)?;
    tokio::time::timeout_at(tokio::time::Instant::from_std(idle_end), socket.readable())
        .await.map_err(|_| refused("resident enrollment expired"))??;
    let (bootstrap, pidfd) = receive_once(socket.as_raw_fd())?;
    validate_bootstrap(&bootstrap)?;
    require_root_pin(&pidfd, peer.pid as u32)?;
    if Instant::now() >= idle_end { return Err(refused("resident enrollment expired")); }
    crate::authority_host_runtime::connect_original_resident_enrollment(
        bootstrap, pidfd, peer.pid as u32, identity, idle_end,
    ).await.map_err(|error| AgentdError::Protocol(error.to_string()))
}

fn receive_once(socket: std::os::fd::RawFd) -> Result<(File, OwnedFd), AgentdError> {
    let mut bytes = [0_u8; FRAME_V3.len() + 1];
    let mut control = [0_usize; 32];
    let mut vector = libc::iovec { iov_base: bytes.as_mut_ptr().cast(), iov_len: bytes.len() };
    // SAFETY: all pointer fields below name bounded buffers retained here.
    let mut message: libc::msghdr = unsafe { mem::zeroed() };
    message.msg_iov = &mut vector; message.msg_iovlen = 1;
    message.msg_control = control.as_mut_ptr().cast(); message.msg_controllen = mem::size_of_val(&control);
    // SAFETY: recvmsg writes only these live buffers and owns received rights
    // with CLOEXEC. A stale readiness indication fails, without another recv.
    let length = unsafe { libc::recvmsg(socket, &mut message, libc::MSG_CMSG_CLOEXEC | libc::MSG_DONTWAIT) };
    if length < 0 { return Err(io::Error::last_os_error().into()); }
    // SAFETY: the original parser consumes only this completed bounded buffer.
    let (mut rights, valid) = unsafe { crate::notes_bootstrap::received_descriptors(&message) };
    if !valid || message.msg_flags & (libc::MSG_TRUNC | libc::MSG_CTRUNC) != 0
        || rights.len() != 2 || length as usize != FRAME_V3.len()
        || &bytes[..FRAME_V3.len()] != FRAME_V3
    { return Err(refused("resident enrollment requires exact purpose and two rights")); }
    let pidfd = rights.pop().ok_or_else(|| refused("resident Root pidfd absent"))?;
    let bootstrap = rights.pop().ok_or_else(|| refused("resident sealed input absent"))?;
    Ok((File::from(bootstrap), pidfd))
}

pub(crate) fn require_original_resident_process_pin(pidfd: &OwnedFd, pid: u32) -> Result<(), AgentdError> {
    require_root_pin(pidfd, pid)
}

